import{t as e}from"./api-B0A8tIVG.js";var t=new class{async getAll(){return(await e.get(`/ecommerce/user/addresses`)).data}async getById(t){return(await e.get(`/ecommerce/user/addresses/${t}`)).data}async create(t){return(await e.post(`/ecommerce/user/addresses`,t)).data}async update(t,n){return(await e.put(`/ecommerce/user/addresses/${t}`,n)).data}async delete(t){await e.delete(`/ecommerce/user/addresses/${t}`)}};export{t};